CREATE DATABASE IF NOT EXISTS covid_portal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE covid_portal;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,phone CHAR(10) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS test_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(32) NOT NULL UNIQUE,patient_name VARCHAR(100) NOT NULL,mobile CHAR(10) NOT NULL,test_date DATE NOT NULL,result ENUM('Pending','Negative','Positive') NOT NULL DEFAULT 'Pending',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX report_lookup (patient_name,mobile,order_number));
CREATE TABLE IF NOT EXISTS appointments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,slot_date DATE NOT NULL,status ENUM('Requested','Confirmed','Cancelled') NOT NULL DEFAULT 'Requested',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT appointments_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX appointment_date (slot_date));
CREATE TABLE IF NOT EXISTS state_stats (state_code CHAR(2) PRIMARY KEY,state_name VARCHAR(80) NOT NULL,tests_done BIGINT UNSIGNED NOT NULL DEFAULT 0,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS comments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,body VARCHAR(1000) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT comments_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
